/** Cut mermaid's browser build into `src/mermaid.gen.ts`, so a ```mermaid
 *  block in a chat draws offline from inside the app bundle: the WebView it
 *  runs in loads a page built from a string (`src/mermaid-page.ts`), with
 *  nothing fetched. The phone reaches its computer over a LAN or a tailnet and
 *  may have no internet at all.
 *
 *  Pinned: mermaid 12.3.0.
 *
 *     npm pack mermaid@12.3.0              (in an empty folder, then untar it)
 *     node scripts/gen-mermaid.cjs <mermaid package dir>
 *
 *  The directory is the unpacked package (the one holding `package.json`). Not
 *  a check, and in no npm script. */
const fs = require('fs');
const path = require('path');

const PINNED = '12.3.0';
const [dir] = process.argv.slice(2);
if (!dir) {
  console.error('usage: node scripts/gen-mermaid.cjs <mermaid package dir>');
  process.exit(2);
}
const read = (f) => fs.readFileSync(path.join(dir, f), 'utf8');
const version = JSON.parse(read('package.json')).version;
if (version !== PINNED) throw new Error(`mermaid ${version} is not the pinned ${PINNED}: change PINNED on purpose`);
// The source map comment points at a file that is not shipped.
const js = read('dist/mermaid.min.js').replace(/\n\/\/# sourceMappingURL=.*\s*$/, '\n');
if (/<\/script/i.test(js)) throw new Error('a closing tag inside the source would end the page early');
const lit = (s) => JSON.stringify(s).replace(/[\u2028\u2029]/g, (c) => `\\u${c.charCodeAt(0).toString(16)}`);

const out = `// Generated by scripts/gen-mermaid.cjs - do not edit.
// mermaid ${version} (MIT License, Copyright (c) 2014 - 2022 Knut Sveidqvist), as
// the text of its browser build (dist/mermaid.min.js), which sets \`mermaid\`
// on the global object.
/* eslint-disable */
export const MERMAID_VERSION = ${JSON.stringify(version)};
export const MERMAID_JS: string = ${lit(js)};
`;
const dest = path.join(__dirname, '..', 'src', 'mermaid.gen.ts');
fs.writeFileSync(dest, out);
console.log(`${dest}: ${out.length} bytes`);
